def clean(df):
    df = df.copy()
    df['body_mass_g'] = df['body_mass_g'].apply(lambda x: x / 1000 if x > 6500 else x)
    df['flipper_length_mm'] = df['flipper_length_mm'].apply(lambda x: abs(x) if x < 0 else x)
    df['sex'] = df['sex'].apply(lambda x: x.strip() if isinstance(x, str) else x)
    return df

def answer(df):
    return df.groupby('species')['body_mass_g'].sum().to_dict()
